<script>
(function() {
  var stateUrl = window.location.origin + "<%= state_moderate_quiz_game_path(@quiz, @game) %>";
  var urls = {
    start: window.location.origin + "<%= start_moderate_quiz_game_path(@quiz, @game) %>",
    finish: window.location.origin + "<%= finish_moderate_quiz_game_path(@quiz, @game) %>",
    advance: window.location.origin + "<%= advance_moderate_quiz_game_path(@quiz, @game) %>",
    endQuiz: window.location.origin + "<%= end_quiz_moderate_quiz_game_path(@quiz, @game) %>",
    top: window.location.origin + "<%= top_winners_moderate_quiz_game_path(@quiz, @game) %>",
    draw: window.location.origin + "<%= draw_winners_moderate_quiz_game_path(@quiz, @game) %>",
    reset: window.location.origin + "<%= reset_winners_moderate_quiz_game_path(@quiz, @game) %>"
  };
  function cleanUrl(url) {
    try {
      var u = new URL(url, window.location.origin);
      u.username = "";
      u.password = "";
      return u.href;
    } catch(e) { return url; }
  }
  var lastStatus = <%= raw @game.status.to_json %>;
  var lastQuestionId = <%= raw((@question&.id).to_json) %>;
  var lastPlayers = <%= @players_count.to_i %>;
  var lastAnswers = <%= (@answers_count || 0).to_i %>;
  var lastTotal = <%= @total.to_i %>;
  var lastNum = <%= (@current_num || 0).to_i %>;
  var lastBoardKey = null;
  var quizTitle = <%= raw @quiz.title.to_s.to_json %>;
  // Preserve QR HTML for lobby re-renders (QR never changes)
  var qrHtml = (function() {
    var el = document.querySelector(".qr");
    return el ? el.outerHTML : '<div class="qr" role="img" aria-label="QR code for join link"></div>';
  })();

  function esc(s) {
    return String(s == null ? "" : s).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");
  }
  function csrfToken() {
    var m = document.querySelector('meta[name="csrf-token"]');
    return m ? m.content : "";
  }
  function boardKey(s) {
    try {
      return JSON.stringify(s.leaderboard || []) + "|" + JSON.stringify(s.winners || []) + "|" + (s.winners_count || "");
    } catch(e) { return ""; }
  }

  function renderLobbyBody(s) {
    return '<div class="lobby"><div>' +
      '<div class="lobby__title">' + esc(s.quiz_title) + '</div>' +
      '<div class="lobby__join">Join at</div>' +
      '<div class="lobby__url" id="join-url">' + esc(s.join_display) + '</div>' +
      '<div class="counter-pill" id="players-counter">Players: ' + s.players_count + '</div>' +
      '</div>' + qrHtml + '</div>';
  }
  function renderOpenBody(s) {
    var q = s.question;
    var html = '<div class="stage-question__num">Question ' + s.current_num + ' of ' + s.total + '</div>' +
      '<div class="stage-question__body">' + esc(q.body) + '</div>' +
      '<ol class="stage-options">';
    for (var i = 0; i < q.options.length; i++) {
      var o = q.options[i];
      var letter = String.fromCharCode(65 + i);
      html += '<li class="stage-option"><span class="stage-option__letter">' + letter + '</span><span class="stage-option__title">' + esc(o.text) + '</span></li>';
    }
    html += '</ol><div class="counter-pill" id="answers-counter">Answers: ' + s.answers_count + ' / ' + s.players_count + '</div>';
    return html;
  }
  function renderClosedBody(s) {
    var q = s.question;
    var totalAns = s.answers_count || 0;
    var html = '<div class="stage-question__num">Question ' + s.current_num + ' of ' + s.total + '</div>' +
      '<div class="stage-question__body">' + esc(q.body) + '</div>' +
      '<ol class="stage-options stage-options--results">';
    for (var i = 0; i < q.options.length; i++) {
      var o = q.options[i];
      var letter = String.fromCharCode(65 + i);
      var pct = totalAns > 0 ? (o.count * 100 / totalAns) : 0;
      html += '<li class="stage-option' + (o.correct ? ' is-correct' : '') + '"><span class="stage-option__bar" style="--share: ' + pct + '%"></span><span class="stage-option__letter">' + letter + '</span><span class="stage-option__title">' + esc(o.text) + '</span><span class="stage-option__count">' + o.count + '</span>' + (o.correct ? '<span class="stage-option__mark">Correct</span>' : '') + '</li>';
    }
    html += '</ol><div class="counter-pill" id="answers-counter">Answers: ' + s.answers_count + ' / ' + s.players_count + '</div>';
    return html;
  }
