  "output_head": "<% if @show_over %>
  <div class="play">
    <div class="play__top"><span class="logo play__logo"><span class="logo__mark">?</span>Quizzy</span><span><%= h @quiz.title %></span></div>
    <div class="play__body">
      <% if @player %>
        <div class="play-lead" id="player-greeting">Hi, <%= h @player.name %>!</div>
      <% end %>
      <div class="play-title" style="margin-top: 12px">The quiz is over</div>
      <% if @result %>
        <div class="result-card">
          <div class="result-card__label" id="player-place"><%= h @result[:place_text] %></div>
          <div class="result-card__score" id="player-points"><%= h @result[:points_text] %></div>
        </div>
        <% if @result[:won] %>
          <div class="winner-banner" id="winner-banner">You won!</div>
        <% end %>
      <% end %>
    </div>
  </div>
  <% if @player %>
  <script>
  (function() {
    var stateUrl = window.location.origin + "<%= play_state_path(code: @game.code) %>";
    var lastPlace = <%= raw((@result ? @result[:place_text] : nil).to_json) %>;
    var lastPoints = <%= raw((@result ? @result[:points_text] : nil).to_json) %>;
    var lastWon = <%= raw((@result ? !!@result[:won] : nil).to_json) %>;
    function poll() {
      fetch(stateUrl, { headers: { "Accept": "application/json" }, credentials: "same-origin", cache: "no-store" })
        .then(function(r) { if (!r.ok) return null; return r.json(); })
        .then(function(s) {
          if (!s || s.status !== "ended" || !s.joined) return;
          var placeText = s.place_text || null;
          var pointsText = s.points_text || null;
          var won = (s.won != null ? !!s.won : null);
          if (placeText !== lastPlace || pointsText !== lastPoints || won !== lastWon) {
            var placeEl = document.getElementById("player-place");
            var pointsEl = document.getElementById("player-points");
            var banner = document.getElementById("winner-banner");
            if (placeEl && placeText) placeEl.textContent = placeText;
            if (pointsEl && pointsText) pointsEl.textContent = pointsText;
            // Handle winner banner live (no reload)
            if (won && !banner) {
              var div = document.createElement("div");
              div.className = "winner-banner";
              div.id = "winner-banner";
              div.textContent = "You won!";
              var body = document.querySelector(".play__body");
              if (body) body.appendChild(div);
            } else if (!won && banner) {
              banner.remove();
            }
            // If result elements missing but we now have data (e.g. leaderboard appeared), create them
            if (!placeEl && placeText) {
              var body2 = document.querySelector(".play__body");
              if (body2) {
                var card = document.createElement("div");
                card.className = "result-card";
                var pl = document.createElement("div");
                pl.className = "result-card__label";
                pl.id = "player-place";
                pl.textContent = placeText;
                var pt = document.createElement("div");
